import 'dart:convert';
import 'package:http/http.dart' as http;
import '../../core/config/api_settings.dart';
import '../models/discount_code_model.dart';
class DiscountCodeApiRepository { final String _initialBaseUrl; String get baseUrl=>ApiSettings.current.baseUrl.isNotEmpty?ApiSettings.current.baseUrl:_initialBaseUrl; DiscountCodeApiRepository({required String baseUrl}):_initialBaseUrl=baseUrl; Future<List<DiscountCodeModel>> getAll()async{final r=await http.get(Uri.parse('$baseUrl/api/discount-codes'));if(r.statusCode==200)return(jsonDecode(r.body)as List<dynamic>).map((e)=>DiscountCodeModel.fromJson(e)).toList();throw Exception('خطا در دریافت لیست کدهای تخفیف');} Future<DiscountCodeModel> create(Map<String,dynamic> data)async{final r=await http.post(Uri.parse('$baseUrl/api/discount-codes'),headers:{'Content-Type':'application/json'},body:jsonEncode(data));if(r.statusCode==200)return DiscountCodeModel.fromJson(jsonDecode(r.body));throw Exception('خطا در ایجاد کد تخفیف');} Future<void> update(int id,Map<String,dynamic> data)async{final r=await http.put(Uri.parse('$baseUrl/api/discount-codes/$id'),headers:{'Content-Type':'application/json'},body:jsonEncode(data));if(r.statusCode!=204)throw Exception('خطا در ویرایش کد تخفیف');} Future<void> delete(int id)async{final r=await http.delete(Uri.parse('$baseUrl/api/discount-codes/$id'));if(r.statusCode!=204)throw Exception('خطا در حذف کد تخفیف');} Future<ValidateDiscountCodeResponse> validate(String code,int personId,double orderAmount)async{final r=await http.post(Uri.parse('$baseUrl/api/discount-codes/validate'),headers:{'Content-Type':'application/json'},body:jsonEncode({'code':code,'personId':personId,'orderAmount':orderAmount}));if(r.statusCode==200)return ValidateDiscountCodeResponse.fromJson(jsonDecode(r.body));throw Exception('خطا در بررسی کد تخفیف');} }
